<?php
require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_permission($conn,'payroll','export');$companyId=oecrm_current_company_id($conn);$runId=oecrm_int_param($_GET,'run_id');$stmt=mysqli_prepare($conn,'SELECT * FROM payroll_runs WHERE id=? AND company_id=? AND status IN ("approved","locked")');mysqli_stmt_bind_param($stmt,'ii',$runId,$companyId);mysqli_stmt_execute($stmt);$run=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$run){http_response_code(403);exit('Bank export is available after payroll approval.');}$rows=mysqli_query($conn,'SELECT e.employeeCode,e.name,e.bankName,e.bankIFSCno,e.bankAcHolderName,e.bankAcNo,p.net_salary FROM payroll_items p JOIN employeestbl e ON e.id=p.employee_id WHERE p.payroll_run_id='.(int)$runId.' AND p.net_salary>0 ORDER BY e.name');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="bank-transfer-'.$run['period_year'].'-'.sprintf('%02d',$run['period_month']).'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Employee Code','Employee Name','Account Holder','Bank Name','IFSC / Routing Code','Account Number','Amount','Currency','Reference']);while($r=mysqli_fetch_assoc($rows)){fputcsv($out,[$r['employeeCode'],$r['name'],$r['bankAcHolderName'],$r['bankName'],$r['bankIFSCno'],$r['bankAcNo'],$r['net_salary'],'INR','SALARY-'.sprintf('%02d',$run['period_month']).'-'.$run['period_year'].'-'.$r['employeeCode']]);}fclose($out);oecrm_audit($conn,'payroll','bank_export','payroll_run',$runId,'Bank transfer file exported');exit;